package android.view;public class ViewGroup extends View {public static class LayoutParams {public int width,height;public LayoutParams(int w,int h){width=w;height=h;}}public final java.util.List<View> children=new java.util.ArrayList<>();public int getChildCount(){return children.size();}public View getChildAt(int n){return children.get(n);}public int indexOfChild(View v){return children.indexOf(v);}public void addView(View v,LayoutParams p){addView(v,children.size(),p);}public void addView(View v,int n,LayoutParams p){if(v.parent!=null)throw new IllegalStateException("already attached");children.add(n,v);v.parent=this;v.params=p;}public void removeView(View v){children.remove(v);v.parent=null;}}
